from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'english','night','Night',
 ('Where does the Sun go?','A short poem wonders where the bright Sun goes at night. It sinks behind a faraway hill, the world grows dark and quiet, and the child sleeps until morning, when the Sun is shining again. In this chapter you will read the poem, think about day and night, play I Spy, practise the sounds sp, st and sk, and make new words with sun.'),
 [('The poem',['The poem asks a simple question: where does the bright Sun go at night?','The answer is that it sinks behind a distant hill, and then the whole world becomes dark and still.','The child goes to bed and sleeps until the day begins to peep, which means to show a little.','When the child opens their eyes in the morning, the Sun is shining again.','So the poem shows the whole day and night in a few lines, from sunset to sunrise.']),
  ('What really happens',['In truth the Sun does not go anywhere. The Earth turns round and round, and the side facing the Sun has day.','When our side turns away from the Sun, it is night for us, and when it turns back, it is morning again.','Plants, flowers, children and animals all need the Sun, because its light and warmth help them grow and stay healthy.','A sunflower and plants need sunlight to make their food. A table and toys do not need the Sun to live.']),
  ('Colours and sights in the sky',['At sunrise and sunset the sky shows orange, red, pink and yellow.','In the night sky we can see the Moon and many stars. During the day we see the Sun, clouds and birds.','When you open your eyes in the morning you may feel fresh and happy, because a new day has begun.']),
  ('New words',['To wonder is to think about something and want to know about it.','Distant means far away. Peep means to look or appear for a short time.']),
  ('The sounds sp, st and sk',['Some words start with two letters that make one quick sound.','Sp words are spy, spin, spoon and splash. St words are star, storm, store, stick, stair and stain. Sk words are sky, skin and skate.','Say each word slowly and listen to how it starts. I spy a few stars in the sky has all three sounds.']),
  ('Sun words',['We can add sun to other words to make new words.','Sun and light make sunlight. Sun and flower make sunflower. Sun and rays make sun rays.','Sun and set make sunset, sun and rise make sunrise, sun and glasses make sunglasses, and sun and day make Sunday.','Each of these is a compound word, made by joining two small words.']),
  ('The game I Spy',['One child is the Spy and secretly chooses something in the room.','The Spy says I spy with my little eye something that is blue, and gives a clue.','Everyone looks around and guesses. If it is tricky, the Spy gives more clues.','The child who guesses right becomes the next Spy.'])],
 [('Make a new word: sun + set.',[('Join the two small words.','We write them together.'),('Sun and set make sunset.','Sunset is the time the Sun goes down.')]),
  ('Which of these are found in the sky: stars, store, moon, bicycle?',[('Think about what we see when we look up.','The sky has the Sun, Moon and stars.'),('Stars and moon are in the sky.','A store and a bicycle are on the ground.')])],
 ('Say what the poem is about and explain where the Sun really goes at night.',['The Sun seems to sink behind a hill','The world grows dark and quiet','The child sleeps and the Sun shines again','The Earth turns, so we have day and night'],['The Sun goes out at night','The Sun moves to another sky']),
 ['The poem wonders where the Sun goes at night.','Day and night happen because the Earth turns.','Sp, st and sk are sounds that start many words.','Sun + word makes sunlight, sunflower, sunset, sunrise and Sunday.','Plants and children need the Sun.'],
 [M('1',1,'What does the poem wonder about?','Where the Sun goes at night',[('Where the Moon goes','The poem is about the Sun'),('Where the stars grow','The poem is about the Sun')],'It asks where the Sun goes.'),
  M('2',1,'Where does the Sun sink, in the poem?','Behind a distant hill',[('Into the sea','The hill is named'),('Behind a house','It is a hill')],'It sinks behind a distant hill.'),
  M('3',1,'Which needs the Sun to live and grow?','Plants',[('A table','A table is not alive'),('Toys','Toys are not alive')],'Plants use sunlight to make food.'),
  M('4',1,'What do we see in the sky at night?','Stars and the Moon',[('The Sun','The Sun is not seen at night'),('Rainbows','Rainbows come with rain and sunlight')],'We see the Moon and stars.'),
  M('5',2,'Which word starts with sp?','Spoon',[('Star','Star starts with st'),('Sky','Sky starts with sk')],'Spoon begins with sp.'),
  M('6',2,'Which word starts with sk?','Skate',[('Storm','Storm starts with st'),('Splash','Splash starts with sp')],'Skate begins with sk.'),
  M('7',2,'Sun + flower makes which word?','Sunflower',[('Sunlight','Light is a different word'),('Sunset','Set is a different word')],'Sun and flower make sunflower.'),
  M('8',2,'Which is not found in the sky?','Bicycle',[('Moon','The Moon is in the sky'),('Clouds','Clouds are in the sky')],'A bicycle is on the ground.'),
  F('9',2,'The Sun really goes out at night.',False,'The Earth turns, so our side faces away.'),
  M('10',2,'What do we call the time the Sun goes down?','Sunset',[('Sunrise','Sunrise is when it comes up'),('Sunlight','Light is the Sun\'s light')],'Sunset is when it goes down.'),
  S('11',2,'What does distant mean?',['far away','far'],'Distant means far away.'),
  M('12',3,'What happens when you open your eyes in the morning, in the poem?','The Sun is shining',[('The Moon is shining','The Sun is shining'),('It is dark','It is morning')],'The poem ends with a shining Sun.')],
 keep=['sunrise','sunset'])
chapter(3,'english','chanda-mama-counts-the-stars','Chanda Mama Counts the Stars',
 ('The Moon who could not finish counting','Chanda Mama, the Moon, tries to count all the stars but always falls asleep or forgets the number. He is upset until the Sun tells him a lovely answer: the number of stars in the sky is the same as the number of children. In this chapter you will read the story, think about things we can and cannot count, use here and there, and write a conversation about the full moon.'),
 [('The story',['Chanda Mama is the Moon. Sometimes he looks round like a circle and sometimes he looks different.','One night he started counting the stars, one, two, three, ten, twenty-one, forty-five, ninety-nine, and so on.','He yawned and fell asleep before he reached a thousand, and the Sun peeped out and the morning came.','When he woke up in the evening he had forgotten where he stopped, and by the time he remembered, the night was over.','Night after night he kept counting and kept forgetting the count.']),
  ('The Sun helps',['One night Chanda Mama was so upset that he began to cry.','The Sun saw his tears and told him not to worry.','The Sun said that the number of lovely children is the same as the number of stars in the sky.','Chanda Mama was happy. Now the Moon comes out every night, looks at the stars and the children, and smiles.']),
  ('Things we can count and cannot count',['Some things we can count easily, like children in the classroom, fingers on one hand and pencils in a box.','Some things are too many to count, like the stars in the sky, the hairs on your head and children in a whole city.','Ask: can I count them in a short time? If yes, they can be counted easily.']),
  ('The Moon',['The Moon does not look the same every night. It changes from a thin curve to a full round shape and back again.','The Moon is seen in the night sky together with stars.','In India children call the Moon Chanda Mama, meaning Uncle Moon. You can call him by the name in your language.']),
  ('New words',['Round means shaped like a circle. To count is to say numbers one by one to find how many.','Tears are drops of water that come from the eyes when we cry.']),
  ('Here and there',['We use here for things that are near to us. We use there for things that are far from us.','I have a sharpener here in my pencil box, because the box is near me.','The crayons are there in the big box across the room, because they are far from me.','We are here on the Earth and the Moon is there in the sky.']),
  ('Writing a conversation',['Children come out on a full moon night and talk about how big and bright the Moon looks.','One says a grandfather says the full moon looks very beautiful. Another says her mother has a camera for the picture.','They decide to stand together and take a photograph, saying the Moon is so big and bright.'])],
 [('Choose here or there: This is my bench. I sit ___ with my friends.',[('The bench is near me; I am pointing at it.','Near things use here.'),('So we write: I sit here with my friends.','There would be for something far away.')]),
  ('Sort: pencils in your box, hairs on your head. Which can be counted easily?',[('Pencils in a box are only a few.','We can count them quickly.'),('Hairs on the head are too many.','We cannot count them easily.'),('So pencils can be counted easily; hairs are too many.','Large numbers are hard to count.')])],
 ('Tell the story of Chanda Mama and explain the Sun\'s answer.',['The Moon tried to count the stars','He fell asleep and forgot the count','The Sun said the stars equal the children','Chanda Mama was happy'],['The Sun counted the stars','The stars were fewer than the children']),
 ['Chanda Mama tried to count the stars but always forgot.','The Sun told him the stars equal the children.','Some things can be counted and some are too many.','Here is for near things and there is for far things.','The Moon changes shape through the month.'],
 [M('1',1,'Who is Chanda Mama?','The Moon',[('The Sun','The Sun helped him'),('A star','He was counting the stars')],'Chanda Mama is the Moon.'),
  M('2',1,'What did Chanda Mama try to count?','The stars',[('The clouds','He counted the stars'),('The children','He counted the stars')],'He counted the stars.'),
  M('3',1,'Why did he fall asleep?','He was sleepy from counting',[('He was sick','He yawned'),('The Sun told him to','Nobody told him')],'He yawned and fell asleep.'),
  M('4',1,'Who helped Chanda Mama?','The Sun',[('The stars','The Sun helped'),('A child','The Sun helped')],'The Sun told him the answer.'),
  M('5',1,'The number of stars in the sky is the same as the number of ___.','children',[('clouds','The Sun said children'),('birds','The Sun said children')],'The Sun said stars equal children.'),
  M('6',2,'Which can be counted easily?','Fingers on one hand',[('Stars in the sky','Too many'),('Hairs on the head','Too many')],'There are only five.'),
  M('7',2,'Which is too many to count?','Stars in the sky',[('Books on your desk','A few'),('Pencils in a box','A few')],'The sky has very many stars.'),
  M('8',2,'Fill in: The Moon is ___ in the sky.','there',[('here','The Moon is far away'),('where','Not a position word')],'The Moon is far, so we say there.'),
  M('9',2,'Fill in: I have a sharpener ___ in my pencil box.','here',[('there','The box is near me'),('then','Not a place word')],'Near things use here.'),
  F('10',2,'The Moon looks the same every night.',False,'It changes shape.'),
  S('11',2,'What do you call the Moon in your language? (Chanda Mama is the Hindi name.)',['chanda mama','chandamama','nilavu','chandrama','moon'],'Any name for the Moon is fine.'),
  M('12',3,'Why did the Moon smile at the end?','He looked at the stars and the children',[('He finished counting','He did not finish'),('He fell asleep','He smiled')],'He was happy about the children.')],
 keep=['Chanda Mama','count'])
